SELECT AVG(CAST(metric_0001 AS DOUBLE PRECISION)) AS avg_metric_0001, AVG(CAST(metric_0025 AS DOUBLE PRECISION)) AS avg_metric_0025, AVG(CAST(metric_0050 AS DOUBLE PRECISION)) AS avg_metric_0050, AVG(CAST(metric_0075 AS DOUBLE PRECISION)) AS avg_metric_0075, AVG(CAST(metric_0100 AS DOUBLE PRECISION)) AS avg_metric_0100 FROM wide100 WHERE time >= '2024-09-23' AND time < '2025-01-01'
